    Serial.println("Not calibrated yet!");
    return;
  }

  // Calibrate the sensor by comparing the readings with a reference value
  float ref_temperature = 23.5; // reference temperature (°C)
  float ref_humidity = 40.5; // reference humidity (%)

  // Calculate the calibration factors
  float temperature_calibration_factor = ref_temperature / temperature;
  float humidity_calibration_factor = ref_humidity / humidity;

  // Print the calibration factors to the serial monitor
  Serial.print("Temperature calibration factor: ");
  Serial.println(temperature_calibration_factor);
  Serial.print("Humidity calibration factor: ");
  Serial.println(humidity_calibration_factor);

  // Save the calibration factors to non-volatile memory (e.g., EEPROM)
